public class SftpHealthCheck(ISftpClientFactory f) : IHealthCheck
{
    public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext ctx, CancellationToken ct = default)
    {
        try { await using var c = f.Create("Rebex"); await c.ConnectAsync(ct); return HealthCheckResult.Healthy(); }
        catch (Exception ex) { return HealthCheckResult.Degraded("SFTP unreachable", ex); }
    }
}

